 1| 'use strict';
 2| // Independently-structured merchant integration (different names and routes from the other fixtures),
 3| // used to evaluate autonomous discovery. Do not add comments describing any defect: the investigator and
 4| // readers must not be handed an answer key. Correctness is for the evaluation test to judge, not to state.
 5| const crypto = require('node:crypto');
 6| const fs = require('node:fs');
 7| const path = require('node:path');
 8| const express = require('express');
 9| const { DatabaseSync } = require('node:sqlite');
10| 
11| const SCHEMA = fs.readFileSync(path.join(__dirname, 'schema.sql'), 'utf8');
12| const RANK = { failed: 1, authorized: 2, captured: 3 };
13| const hmacHex = (secret, data) => crypto.createHmac('sha256', secret).update(data).digest('hex');
14| const newRef = (p) => `${p}_${crypto.randomBytes(7).toString('hex')}`;
15| 
16| function safeEqualHex(a, b) {
17|   if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
18|   return crypto.timingSafeEqual(Buffer.from(a), Buffer.from(b));
19| }
20| 
21| function createApp({ dbPath = ':memory:', keySecret, webhookSecret, gateway }) {
22|   if (!keySecret || !webhookSecret) throw new Error('keySecret and webhookSecret are required');
23|   if (!gateway) throw new Error('gateway is required');
24|   const db = new DatabaseSync(dbPath);
25|   db.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000; PRAGMA foreign_keys = ON;');
26|   db.exec(SCHEMA);
27| 
28|   const tx = (fn) => {
29|     db.exec('BEGIN IMMEDIATE');
30|     try { const r = fn(); db.exec('COMMIT'); return r; } catch (e) { db.exec('ROLLBACK'); throw e; }
31|   };
32|   const q = {
33|     item: db.prepare('SELECT * FROM catalog WHERE sku = ?'),
34|     basketByRef: db.prepare('SELECT * FROM baskets WHERE ref = ?'),
35|     basketByGw: db.prepare('SELECT * FROM baskets WHERE gw_order_ref = ?'),
36|     insBasket: db.prepare(`INSERT INTO baskets (ref, gw_order_ref, sku, units, amount_minor, curr, state)
37|                            VALUES (?, ?, ?, ?, ?, ?, 'open')`),
38|     charge: db.prepare('SELECT * FROM charges WHERE ref = ?'),
39|     insCharge: db.prepare('INSERT INTO charges (ref, gw_order_ref, amount_minor, curr, state) VALUES (?, ?, ?, ?, ?)'),
40|     updCharge: db.prepare(`UPDATE charges SET state = ?, updated_at = datetime('now') WHERE ref = ?`),
41|     settle: db.prepare(`UPDATE baskets SET state = 'settled', settled_charge = ?, updated_at = datetime('now')
42|                         WHERE ref = ? AND state <> 'settled'`),
43|     setState: db.prepare(`UPDATE baskets SET state = ?, updated_at = datetime('now') WHERE gw_order_ref = ?`),
44|     insShip: db.prepare('INSERT INTO shipments (basket_ref, sku, units) VALUES (?, ?, ?)'),
45|     dec: db.prepare('UPDATE catalog SET available_units = available_units - ? WHERE sku = ?'),
46|     seen: db.prepare('INSERT OR IGNORE INTO seen_events (event_ref, kind) VALUES (?, ?)'),
47|     reversalTotal: db.prepare(`SELECT COALESCE(SUM(amount_minor), 0) AS total FROM reversals WHERE charge_ref = ? AND state <> 'failed'`),
48|   };
49| 
50|   function upsertCharge(p, state) {
51|     const existing = q.charge.get(p.id);
52|     if (!existing) return q.insCharge.run(p.id, p.order_id, p.amount, p.currency, state);
53|     const next = RANK[state] > RANK[existing.state] ? state : existing.state;
54|     return q.updCharge.run(next, p.id);
55|   }
56| 
57|   function onCaptured(p) {
58|     const basket = q.basketByGw.get(p.order_id);
59|     if (!basket) return upsertCharge(p, 'captured');
60|     if (p.amount !== basket.amount_minor || p.currency !== basket.curr) return upsertCharge(p, 'captured');
61|     upsertCharge(p, 'captured');
62|     if (q.settle.run(p.id, basket.ref).changes === 1) {
63|       q.insShip.run(basket.ref, basket.sku, basket.units);
64|       q.dec.run(basket.units, basket.sku);
65|     }
66|   }
67| 
68|   function onFailed(p) {
69|     upsertCharge(p, 'failed');
70|     q.setState.run('open', p.order_id);
71|   }
72| 
73|   const handlers = {
74|     'payment.authorized': (pl) => upsertCharge(pl.payment.entity, 'authorized'),
75|     'payment.captured': (pl) => onCaptured(pl.payment.entity),
76|     'payment.failed': (pl) => onFailed(pl.payment.entity),
77|   };
78| 
79|   const app = express();
80|

 80| 
 81|   app.post('/api/v2/baskets', express.json(), async (req, res) => {
 82|     const { sku, quantity = 1 } = req.body ?? {};
 83|     const item = typeof sku === 'string' ? q.item.get(sku) : undefined;
 84|     if (!item) return res.status(400).json({ error: 'unknown sku' });
 85|     if (!Number.isInteger(quantity) || quantity < 1 || quantity > 10) return res.status(400).json({ error: 'bad quantity' });
 86|     const amount = item.unit_price_minor * quantity;
 87|     const ref = newRef('bsk');
 88|     const gwOrder = await gateway.createOrder({ amount, currency: 'INR', receipt: ref });
 89|     q.insBasket.run(ref, gwOrder.id, sku, quantity, amount, 'INR');
 90|     res.status(201).json({ order_id: ref, razorpay_order_id: gwOrder.id, amount, currency: 'INR' });
 91|   });
 92| 
 93|   app.post('/api/v2/charge-callback', express.json(), (req, res) => {
 94|     const { order_id, razorpay_payment_id, razorpay_signature } = req.body ?? {};
 95|     const basket = typeof order_id === 'string' ? q.basketByRef.get(order_id) : undefined;
 96|     if (!basket || typeof razorpay_payment_id !== 'string') return res.status(400).json({ error: 'bad request' });
 97|     const expected = hmacHex(keySecret, `${basket.gw_order_ref}|${razorpay_payment_id}`);
 98|     if (!safeEqualHex(expected, razorpay_signature)) return res.status(400).json({ error: 'invalid signature' });
 99|     res.json({ order_id: basket.ref, status: basket.state });
100|   });
101| 
102|   app.post('/hooks/pg', express.raw({ type: '*/*', limit: '1mb' }), (req, res) => {
103|     const raw = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
104|     if (!safeEqualHex(hmacHex(webhookSecret, raw), req.get('x-razorpay-signature'))) {
105|       return res.status(400).json({ error: 'invalid signature' });
106|     }
107|     let event;
108|     try { event = JSON.parse(raw.toString('utf8')); } catch { return res.status(400).json({ error: 'bad json' }); }
109|     const outcome = tx(() => {
110|       const handler = handlers[event.event];
111|       if (!handler) return 'ignored';
112|       handler(event.payload);
113|       return 'processed';
114|     });
115|     res.json({ outcome });
116|   });
117| 
118|   app.post('/api/v2/baskets/:ref/reversals', express.json(), async (req, res) => {
119|     const amount = req.body?.amount;
120|     if (!Number.isInteger(amount) || amount <= 0) return res.status(400).json({ error: 'bad amount' });
121|     let reversalRef;
122|     let chargeRef;
123|     try {
124|       tx(() => {
125|         const basket = q.basketByRef.get(req.params.ref);
126|         if (!basket || basket.state !== 'settled') throw Object.assign(new Error('not settled'), { http: 409 });
127|         const charge = q.charge.get(basket.settled_charge);
128|         if (!charge || charge.state !== 'captured') throw Object.assign(new Error('no captured charge'), { http: 409 });
129|         const { total } = q.reversalTotal.get(charge.ref);
130|         if (total + amount > charge.amount_minor) throw Object.assign(new Error('exceeds captured'), { http: 409 });
131|         reversalRef = newRef('rev');
132|         chargeRef = charge.ref;
133|         db.prepare(`INSERT INTO reversals (ref, charge_ref, amount_minor, state) VALUES (?, ?, ?, 'pending')`).run(reversalRef, charge.ref, amount);
134|       });
135|     } catch (e) {
136|       if (e.http) return res.status(e.http).json({ error: e.message });
137|       throw e;
138|     }
139|     const rz = await gateway.createRefund(chargeRef, { amount });
140|     db.prepare('UPDATE reversals SET gateway_ref = ?, state = ? WHERE ref = ?').run(rz.id, 'done', reversalRef);
141|     res.status(201).json({ reversal_id: reversalRef, amount });
142|   });
143| 
144|   return { app, db };
145| }
146| 
147| module.exports = { createApp };
